// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Collection } from '@stdlib/types/array';
import { Iterator as Iter, IterableIterator } from '@stdlib/types/iter';

// Define a union type representing both iterable and non-iterable iterators:
type Iterator = Iter | IterableIterator;

/**
* Returns an iterator which iterates over the Cartesian square of an array-like object.
*
* ## Notes
*
* -   The Cartesian square is equivalent to the Cartesian product of an array-like object with itself.
* -   The order of the returned tuples follows the order of iteration of the provided array-like object, with elements of the second tuple component varying fastest.
* -   If provided an empty array-like object, the returned iterator is empty.
* -   If an environment supports `Symbol.iterator`, the returned iterator is iterable.
*
* @param x - input array
* @throws argument must be an array-like object
* @returns iterator
*
* @example
* var iter = iterCartesianSquare( [ 1, 2 ] );
*
* var v = iter.next().value;
* // returns [ 1, 1 ]
*
* v = iter.next().value;
* // returns [ 1, 2 ]
*
* v = iter.next().value;
* // returns [ 2, 1 ]
*
* // ...
*/
declare function iterCartesianSquare( x: Collection ): Iterator;


// EXPORTS //

export = iterCartesianSquare;
